// @grant       GM_setValue
// @grant       GM_registerMenuCommand
// @grant       GM_addStyle
// @run-at      document-start
// ==/UserScript==

(function () {
  'use strict';

  try { window.__hsVer = '0.0.1'; window.__hsErr = null; } catch (e) {}

  const ASSETS = {
    batSheet: 'data:image/png;base64,',
    moon: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path fill="#fff" d="M253.125 18.563c-131.53 0-238.375 106.813-238.375 238.343 0 131.53 106.846 238.344 238.375 238.344 131.53 0 238.344-106.815 238.344-238.344 0-131.528-106.816-238.344-238.345-238.344zm-23.938 52.093c40.517 0 77.988 12.904 108.532 34.813a154.099 154.099 0 0 0-17.064-.97c-84.157 0-152.375 68.25-152.375 152.406 0 84.157 68.22 152.375 152.376 152.375 5.762 0 11.467-.313 17.063-.936-30.545 21.91-68.016 34.812-108.533 34.812-102.98 0-186.28-83.272-186.28-186.25 0-102.977 83.3-186.25 186.28-186.25z"/></svg>`,
    graveyard: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path fill="#fff" d="M128 73c-25.495 0-44.07 6.4-55.97 13.86C60.134 94.32 56 103.84 56 104.63v40.274c6.343 2.532 12.03 5.422 17.023 8.545C89.79 163.94 100 175.957 100 189.542v59.57c8.63-1.35 17.956-2.113 28-2.113s19.37.764 28 2.113v-59.57c0-13.585 10.21-25.604 26.977-36.094 4.992-3.124 10.68-6.014 17.023-8.546V104.63c0-.792-4.133-10.31-16.03-17.77C172.07 79.4 153.494 73 128 73zm256 0c-25.495 0-44.07 6.4-55.97 13.86-11.896 7.46-16.03 16.98-16.03 17.77v40.274c6.343 2.532 12.03 5.422 17.023 8.545C345.79 163.94 356 175.957 356 189.542v59.57c8.63-1.35 17.956-2.113 28-2.113s19.37.764 28 2.113v-59.57c0-13.585 10.21-25.604 26.977-36.094 4.992-3.124 10.68-6.014 17.023-8.546V104.63c0-.792-4.133-10.31-16.03-17.77C428.07 79.4 409.494 73 384 73zM119 91.086h18v31.63h45v18h-45v99.34h-18v-99.34H74v-18h45v-31.63zm256 0h18v31.63h45v18h-45v99.34h-18v-99.34h-45v-18h45v-31.63zM256 153c-28.832 0-49.91 7.222-63.477 15.71C178.958 177.195 174 187.946 174 189.542v63.494c12.076 3.43 22.355 8.07 30.77 13.33C222.37 277.367 233 290 233 304v58.715h46V304c0-14 10.63-26.632 28.23-37.633 8.415-5.26 18.694-9.9 30.77-13.33v-63.494c0-1.596-4.958-12.347-18.523-20.834C305.91 160.22 284.832 153 256 153zm-238 1.016v56.888h42.666v18H18v133.81h5V304c0-14 10.63-26.632 28.23-37.633 8.415-5.26 18.694-9.9 30.77-13.33v-63.494c0-1.596-4.958-12.347-18.523-20.834C52.917 162.1 37.78 156.28 18 154.015zm476 0c-19.78 2.263-34.916 8.086-45.477 14.693C434.958 177.195 430 187.946 430 189.542v63.494c12.076 3.43 22.355 8.07 30.77 13.33C478.37 277.367 489 290 489 304v58.715h5v-133.81h-42.666v-18H494v-56.89zM247 174.36h18v36.544h51.666v18H265v112.448h-18V228.904h-51.666v-18H247V174.36zM128 265c-30.5 0-52.83 7.633-67.23 16.633C46.37 290.633 41 302 41 304v183h174V304c0-2-5.37-13.368-19.77-22.367-14.4-9-36.73-16.633-67.23-16.633zm256 0c-30.5 0-52.83 7.633-67.23 16.633C302.37 290.633 297 302 297 304v183h174V304c0-2-5.37-13.368-19.77-22.367-14.4-9-36.73-16.633-67.23-16.633zm-265 23h18v39h55v18h-55v119h-18V345H64v-18h55v-39zm256 0h18v39h55v18h-55v119h-18V345h-55v-18h55v-39z"/></svg>`,
    pumpkin: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path fill="#ff9b21" d="M252.5 21.156c-16.98.22-33.708 4.552-49.72 13.313l-4.593 2.5-.25 5.218c-.71 14.473-.49 33.985 3.063 52.968-45.775 2.55-84.144 20.94-113.094 48.625C48.312 181.647 25.87 236.18 22.47 291c-3.402 54.82 12.32 110.396 50.5 149.563 38.01 38.994 98.086 60.67 179.843 49.437 91.743 8.826 154.664-13.978 192-53.906 37.494-40.1 48.374-96.148 39.968-150.563-8.404-54.413-35.9-107.795-76.905-144.53-30.753-27.55-69.526-45.58-112.813-46.688-6.366-.163-12.823.077-19.375.688 1.99-18.702 8.107-36.836 18.282-54.75l5.717-10.03-11-3.5c-10.928-3.484-21.894-5.354-32.78-5.564-1.135-.022-2.275-.014-3.407 0zm.594 18.5c.826-.005 1.64.012 2.47.032 5.472.13 11.025.846 16.655 2.03-14.398 29.89-19.03 61.625-13.314 94.282-8.162 1.28-13.987-.206-18.844-3.25-6.315-3.958-11.562-11.503-15.406-21.594-7.026-18.446-8.592-43.953-8.125-62.625 12.073-5.82 24.17-8.79 36.564-8.874zm36.812 73.22c1.623-.017 3.238-.007 4.844.03 26.418.605 50.73 8.318 72.438 21.188-6.758 10.28-19.022 19.106-35.563 25.78-21.344 8.614-49.05 13.303-77.063 13.5-28.012.2-56.365-4.08-79.093-12.5-18.705-6.928-33.23-16.595-41.532-28.093 20.665-11.46 44.554-18.416 71.687-19.28.486 1.454 1.022 2.892 1.563 4.313 4.727 12.41 11.81 23.756 22.968 30.75 11.158 6.993 25.952 8.577 42.406 3.343l8.22-2.625-1.97-8.405c-2.15-9.21-3.372-18.236-3.718-27.125 5.003-.54 9.945-.827 14.812-.875zm-171.78 29.968c11.135 16.145 29.513 27.66 50.843 35.562 25.507 9.45 55.785 13.868 85.75 13.656 29.962-.21 59.59-5.03 83.905-14.843 18.664-7.533 34.624-18.224 44.125-32.69 4.345 3.26 8.565 6.71 12.656 10.376 37.356 33.467 63.165 83.352 70.906 133.47 7.742 50.116-2.365 99.87-35.156 134.937-32.79 35.067-89.1 56.757-177.656 48l-1.125-.094-1.094.155c-77.94 10.96-131.157-9.192-164.936-43.844-33.78-34.65-48.35-84.885-45.22-135.374 3.133-50.488 24.058-100.77 59.688-134.844 5.438-5.2 11.21-10.05 17.313-14.468zm55.06 59.28c-17.525 19.402-30.988 41.834-41.03 66.845l78.563 2.936c-9.76-26.926-22.16-50.34-37.532-69.78zm168.033 1.407c-19.43 0-35.19 15.756-35.19 35.19 0 19.43 15.76 35.186 35.19 35.186s35.155-15.755 35.155-35.187c0-19.436-15.726-35.19-35.156-35.19zM62.31 321.876c10.71 51.276 48.785 85.54 97.157 103.875L164.5 400l40 7.688-5.656 29.125c20.105 3.882 41.064 5.448 61.937 4.812l-3.25-29.22 47.283-5.25 3.25 29.158c24.27-4.824 47.335-12.838 67.562-23.875l-11.094-29.375 38.876-17.625 8.03 21.25c18.428-17.576 31.46-39.23 36.408-64.813-31.205 9.386-64.876 16.156-99.656 20.375l3.656 26.844L303.97 377l-4.19-30.563c-14.542.79-29.185 1.157-43.81 1.125l-1.814 33.813-48.312-3.47 1.72-31.936c-14.844-.943-29.6-2.267-44.126-4.033l-8.844 35.25-40.563-6.78 8.657-34.626c-20.89-3.765-41.127-8.4-60.374-13.905z"/></svg>`,
    tombstone: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path fill="#3f382b" d="M253.75 18.906c-77.635.03-154.875 54.01-154.875 167.5v209.72c25.67 19.717 46.68 41.386 52.156 69.124-3.507-44.464-4.166-88.692 14.595-133.156 5.265 38.52 8.087 77.137 26.875 115.656 25.316-53.302 59.948-75.555 102.188-72.438-29.706 25.94-56.26 55.26-74.75 95.22 31.477-30.2 66.886-38.728 103.968-40.907-21.57 15.247-41.576 30.414-54.156 50.22h78.344c6.443-27.99-4.756-54.648-17.78-82.908 27.59 18.168 51.09 40.4 61.905 77.657 3.525-39-3.843-73.686-15.19-106.875 13.34 6.44 23.875 15.568 31.595 27.374V186.406c0-113.616-77.24-167.528-154.875-167.5zM150.156 144.594h114.938v18.687H150.156v-18.686zm152.438 0h56.125v18.687h-56.126v-18.686zm-152.438 42.75h36.5v18.687h-36.5v-18.686zm72.25 0H358.72v18.687H222.405v-18.686zm-72.28 40.312h95.81v18.688h-95.81v-18.688zm126.31 0h82.283v18.688h-82.283v-18.688zm-177.56 189.53v62.658h23.686c-4.638-21.58-13.086-42.375-23.687-62.656z"/></svg>`,
    tombstone2: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path fill="#3f382b" d="M256 46c-81.822 0-150 63.366-150 150v150c0 6.668-.757 23.558 0 30h300c.757-6.442 0-23.332 0-30V196c0-86.634-68.178-150-150-150zM16 406v60h480v-60H16z"/></svg>`,
    coffin: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path fill="#3f382b" d="m312.094 21.97 59.094 119.686h52.093L362.595 22l-50.5-.03zM173 22.687l-63.594 127.218 65.844 345.75 114.688.094L354.467 150 291.626 22.75 173 22.687zm16.063 76.28h88.78v18.688h-88.78V98.97zm0 36.22h88.78v18.687h-88.78v-18.688zm182.5 25.156L309 495.438l47.25.03 68.313-335.124h-53z"/></svg>`
  };

  const CSS = `
@font-face{font-family:'HSCreepster';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'HSCinzel';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
#hs-sky{position:fixed;inset:0;z-index:2147482000;pointer-events:none;opacity:0;transition:opacity 2.5s ease;background:linear-gradient(180deg,#04040f 0%,#141033 50%,#33134a 100%)}
#hs-sky.hs-on{opacity:.40}
#hs-moon{position:fixed;top:7vh;right:7vw;width:118px;height:118px;z-index:2147482010;pointer-events:none;opacity:0;transform:translateY(115vh);transition:transform 2.6s cubic-bezier(.25,.65,.3,1),opacity .9s ease}
#hs-moon.hs-on{opacity:1;transform:translateY(0)}
#hs-moon svg{width:100%;height:100%;display:block;filter:drop-shadow(0 0 12px rgba(255,228,170,.95)) drop-shadow(0 0 44px rgba(255,188,92,.55))}
#hs-graveyard{position:fixed;left:6px;bottom:0;width:155px;z-index:2147482005;pointer-events:none;opacity:0;transition:opacity 2.8s ease .4s}
#hs-graveyard.hs-on{opacity:.55}
#hs-graveyard svg{width:100%;height:auto;display:block}
.hs-bat{position:fixed;top:0;left:0;width:64px;height:64px;z-index:2147482050;pointer-events:none;background-size:400% 400%;background-repeat:no-repeat;background-position:0% 0%;image-rendering:pixelated;will-change:transform;filter:drop-shadow(0 8px 5px rgba(0,0,0,.35))}
.hs-tomb{position:relative;background:linear-gradient(176deg,#f4efe3 0%,#ded6c3 100%)!important;border:1px solid #a79e87!important;border-radius:12px!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.75),0 7px 15px rgba(0,0,0,.35)!important;padding:12px 16px 14px!important;margin:9px 0!important}
.hs-epitaph{display:flex!important;align-items:center;gap:8px;margin-top:8px;color:#4b4334;font-family:'HSCinzel',Georgia,'Times New Roman',serif!important;font-weight:700;font-size:12.5px!important;font-style:italic;letter-spacing:.2px;line-height:1.35}
.hs-epitaph img{width:20px;height:20px;flex:0 0 20px;opacity:.75}
#hs-counter{position:fixed;right:16px;bottom:16px;z-index:2147482099;display:none;align-items:center;gap:9px;padding:9px 15px;border-radius:999px;background:rgba(15,8,26,.93);border:2px solid #7c4db8;color:#ffcf85;font-family:'HSCreepster','Creepster',Impact,fantasy;font-size:16px;letter-spacing:.6px;box-shadow:0 8px 20px rgba(0,0,0,.55);pointer-events:auto;max-width:72vw}
#hs-counter.hs-on{display:flex}
#hs-counter img{width:20px;height:20px}
input[name="q"].hs-glitch,textarea[name="q"].hs-glitch{animation:hs-glitch 7.5s infinite}
@keyframes hs-glitch{0%,82%,100%{text-shadow:none}84%{text-shadow:-1.5px 0 rgba(255,0,80,.9),1.5px 0 rgba(0,255,180,.9)}87%{text-shadow:1.5px 0 rgba(140,0,255,.9),-1.5px 0 rgba(255,120,0,.9)}90%{text-shadow:-1.5px 0 rgba(0,255,180,.9),1.5px 0 rgba(255,0,80,.9)}93%{text-shadow:1.5px 0 rgba(255,120,0,.9),-1.5px 0 rgba(140,0,255,.9)}96%{text-shadow:none}97%{text-shadow:-1.5px 0 rgba(255,0,80,.9),1.5px 0 rgba(0,255,180,.9)}99%{text-shadow:none}}
@media (prefers-reduced-motion:reduce){#hs-sky,#hs-moon,#hs-graveyard{transition:none}.hs-glitch{animation:none}}
`;

  const EPITAPH_ICONS = [ASSETS.tombstone, ASSETS.tombstone2, ASSETS.coffin];

  const TEMPLATES = [
    (t, n) => `Here lies \u201C${t}\u201D — it survived ${n} clicks`,
    (t, n) => `\u201C${t}\u201D — gone, but not forgotten (${1990 + (n % 30)})`,
    (t, n) => `${n} candles were lit for \u201C${t}\u201D`,
    (t, n) => `R.I.P. — \u201C${t}\u201D, missed by ${n} souls`
  ];

  const state = { active: false, bats: [], raf: 0, last: 0, observer: null, seen: new WeakSet(), mx: -9999, my: -9999 };
  let enabled = true;
  try { enabled = GM_getValue('hs-enabled', true); } catch (e) {}
  try { window.__hsEnabled = enabled; } catch (e) {}

  function query() {
    try { return new URLSearchParams(location.search).get('q') || ''; } catch (e) { return ''; }
  }

  function wantsScene() {
    return enabled && /\bhalloween\b/i.test(query().trim());
  }

  function hash(s) {
    let h = 0;
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
    return Math.abs(h);
  }

  function svgImg(svg) {
    const img = document.createElement('img');
    img.alt = '';
    img.src = 'data:image/svg+xml;base64,' + btoa(svg);
    return img;
  }

  function ensureLayers() {
    const host = document.body;
    if (!host) return;
    if (!document.getElementById('hs-sky')) {
      const sky = document.createElement('div');
      sky.id = 'hs-sky';
      host.appendChild(sky);
    }
    if (!document.getElementById('hs-moon')) {
      const moon = document.createElement('div');
      moon.id = 'hs-moon';
      moon.innerHTML = ASSETS.moon;
      host.appendChild(moon);
    }
    if (!document.getElementById('hs-graveyard')) {
      const gy = document.createElement('div');
      gy.id = 'hs-graveyard';
      gy.innerHTML = ASSETS.graveyard;
      host.appendChild(gy);
    }
    if (!document.getElementById('hs-counter')) {
      const c = document.createElement('div');
      c.id = 'hs-counter';
      c.appendChild(svgImg(ASSETS.pumpkin));
      c.appendChild(document.createElement('span'));
      host.appendChild(c);
    }
  }

  function ensureBats() {
    if (state.bats.length || !document.body) return;
    for (let i = 0; i < 8; i++) {
      const el = document.createElement('div');
      el.className = 'hs-bat';
      el.style.backgroundImage = 'url("' + ASSETS.batSheet + '")';
      document.body.appendChild(el);
      state.bats.push({
        el: el,
        x: Math.random() * window.innerWidth,
        baseY: 40 + Math.random() * Math.max(80, window.innerHeight - 140),
        bob: 0,
        vx: (Math.random() > 0.5 ? 1 : -1) * (45 + Math.random() * 85),
        amp: 24 + Math.random() * 55,
        freq: 0.45 + Math.random() * 0.8,
        ph: Math.random() * Math.PI * 2,
        dir: 1,
        frame: Math.floor(Math.random() * 16),
        flast: 0,
        avoid: 0
      });
    }
  }

  function loop(ts) {
    if (!state.active) return;
    const dt = Math.min(64, ts - (state.last || ts)) / 1000;
    state.last = ts;
    const W = window.innerWidth;
    const H = window.innerHeight;
    for (const b of state.bats) {
      b.x += b.vx * dt;
      b.bob = Math.sin((ts / 1000) * b.freq * Math.PI * 2 + b.ph) * b.amp;
      let y = b.baseY + b.bob;
      const dx = b.x - state.mx;
      const dy = y - state.my;
      const d = Math.hypot(dx, dy);
      if (d < 150 && d > 1) b.avoid = Math.min(110, b.avoid + (150 - d) * 0.12);
      b.avoid *= 0.93;
      if (d > 1) y += (dy / d) * b.avoid;
      y = Math.max(-24, Math.min(H - 44, y));
      if (b.x > W + 90) b.x = -90;
      if (b.x < -90) b.x = W + 90;
      b.dir = b.vx >= 0 ? 1 : -1;
      b.el.style.transform = 'translate3d(' + b.x + 'px,' + y + 'px,0) scaleX(' + b.dir + ')';
      if (ts - b.flast > 85) {
        b.flast = ts;
        b.frame = (b.frame + 1) % 16;
        const col = b.frame % 4;
        const row = (b.frame / 4) | 0;
        b.el.style.backgroundPosition = col * (100 / 3) + '% ' + row * (100 / 3) + '%';
      }
    }
    state.raf = requestAnimationFrame(loop);
  }

  function decorate() {
    if (!state.active) return;
    const heads = document.querySelectorAll('#search h3, #rso h3, .MjjYud h3, .MjjYud [role="heading"], #search [role="heading"], #rso [role="heading"]');
    heads.forEach(function (h) {
      try {
        const prev = h.nextElementSibling;
        if (prev && prev.classList && prev.classList.contains('hs-epitaph')) return;
        if (state.seen.has(h)) return;
        let el = h.closest('.MjjYud') || h.closest('.g') || h.closest('#rso > div') || h.closest('#search #rso > div');
        if (!el) {
          el = h.parentElement;
          for (let i = 0; i < 6 && el; i++) {
            if (el.querySelector('a[href]')) break;
            el = el.parentElement;
          }
        }
        if (!el) return;
        if (el.classList.contains('hs-tomb')) return;
        if (!el.querySelector('a[href]')) return;
        const title = h.textContent.trim();
        if (!title) return;
        state.seen.add(h);
        el.classList.add('hs-tomb');
        const seed = hash(title);
        const n = (seed % 60) + 2;
        const shown = title.length > 48 ? title.slice(0, 45) + '\u2026' : title;
        const text = TEMPLATES[seed % TEMPLATES.length](shown, n);
        const ep = document.createElement('div');
        ep.className = 'hs-epitaph';
        try { ep.appendChild(svgImg(EPITAPH_ICONS[seed % EPITAPH_ICONS.length])); } catch (eIcon) {}
        ep.appendChild(document.createTextNode(text));
        h.after(ep);
      } catch (e) { try { window.__hsErr = String((e && e.stack) || e); } catch (_) {} }
    });
  }

  function start() {
    if (state.active || !document.body) return;
    ensureLayers();
    ensureBats();
    state.active = true;
    state.last = 0;
    state.seen = new WeakSet();
    document.getElementById('hs-sky').classList.add('hs-on');
    document.getElementById('hs-moon').classList.add('hs-on');
    document.getElementById('hs-graveyard').classList.add('hs-on');
    const counter = document.getElementById('hs-counter');
    const haunts = GM_getValue('hs-haunts', 0) + 1;
    GM_setValue('hs-haunts', haunts);
    counter.querySelector('span').textContent = haunts + ' bat' + (haunts === 1 ? '' : 's') + (haunts === 1 ? ' has' : ' have') + ' haunted your searches';
    counter.classList.add('hs-on');
    state.bats.forEach(function (b) { b.el.style.display = ''; });
    document.querySelectorAll('input[name="q"],textarea[name="q"]').forEach(function (el) {
      el.classList.add('hs-glitch');
    });
    decorate();
    if (!state.observer) {
      state.observer = new MutationObserver(function () { try { decorate(); } catch (e) { try { window.__hsErr = String((e && e.stack) || e); } catch (_) {} } });
      state.observer.observe(document.body, { childList: true, subtree: true });
    }
    state.raf = requestAnimationFrame(loop);
  }

  function stop() {
    if (!state.active) return;
    state.active = false;
    cancelAnimationFrame(state.raf);
    if (state.observer) {
      state.observer.disconnect();
      state.observer = null;
    }
    ['hs-sky', 'hs-moon', 'hs-graveyard', 'hs-counter'].forEach(function (id) {
      const el = document.getElementById(id);
      if (el) el.classList.remove('hs-on');
    });
    state.bats.forEach(function (b) { b.el.style.display = 'none'; });
    document.querySelectorAll('.hs-glitch').forEach(function (el) { el.classList.remove('hs-glitch'); });
    document.querySelectorAll('.hs-tomb').forEach(function (el) { el.classList.remove('hs-tomb'); });
    document.querySelectorAll('.hs-epitaph').forEach(function (el) { el.remove(); });
    state.seen = new WeakSet();
  }

  function tick() {
    const want = wantsScene();
    if (want && !state.active) start();
    else if (!want && state.active) stop();
    if (state.active) {
      document.querySelectorAll('input[name="q"],textarea[name="q"]').forEach(function (el) {
        if (!el.classList.contains('hs-glitch')) el.classList.add('hs-glitch');
      });
    }
  }

  try { GM_addStyle(CSS); } catch (e) { try { window.__hsErr = 'style:' + String(e); } catch (_) {} }

  try {
    GM_registerMenuCommand('Toggle Halloween scene', function () {
      enabled = !enabled;
      try { GM_setValue('hs-enabled', enabled); } catch (e) {}
      try { window.__hsEnabled = enabled; } catch (e) {}
      try { tick(); } catch (e) { try { window.__hsErr = String((e && e.stack) || e); } catch (_) {} }
    });
  } catch (e) {}

  try {
    GM_registerMenuCommand('Reset haunted counter', function () {
      try { GM_setValue('hs-haunts', 0); } catch (e) {}
      const c = document.getElementById('hs-counter');
      if (c && c.querySelector('span')) c.querySelector('span').textContent = '0 bats have haunted your searches';
    });
  } catch (e) {}

  window.addEventListener('mousemove', function (e) {
    state.mx = e.clientX;
    state.my = e.clientY;
  }, { passive: true });

  setInterval(function () { try { tick(); } catch (e) { try { window.__hsErr = String((e && e.stack) || e); } catch (_) {} } }, 1000);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { try { tick(); } catch (e) { try { window.__hsErr = String((e && e.stack) || e); } catch (_) {} } });
  } else {
    try { tick(); } catch (e) { try { window.__hsErr = String((e && e.stack) || e); } catch (_) {} }
  }
})();



